/* 咪哆豆多拼豆馆管理端 */
let currentZone = 'A';
let selectedSeat = null;
let selectedPackageId = null;
let selectedPartySize = 1;
let selectedSeatIds = [];
let pendingEditArrival = '到店';
let pendingEditStatus = '未付款';
let timerInterval = null;

window.addEventListener('DOMContentLoaded', () => {
  initZoneTabs();
  renderStats();
  renderActionSummary();
  renderSeats();
  renderIronQueue();
  startTimer();
  window.addEventListener('storage', refreshAll);
  window.addEventListener('pindou:state-change', refreshAll);
});

function refreshAll() { renderStats(); renderActionSummary(); renderSeats(); renderIronQueue(); }
function initZoneTabs() {
  document.querySelectorAll('.zone-tab').forEach(tab => tab.addEventListener('click', () => {
    currentZone = tab.dataset.zone;
    document.querySelectorAll('.zone-tab').forEach(x => x.classList.remove('active'));
    tab.classList.add('active');
    renderSeats();
  }));
}
function renderStats() {
  const s = getTodayStats();
  const set = (id, value) => { const el = document.getElementById(id); if (el) el.textContent = value; };
  const states = Object.values(getAllSeatStates());
  const liveOvertime = new Set(states.filter(x => isOvertime(x)).map(x => x.orderId || x.seatId)).size;
  const ironItems = getIronQueue();
  const pendingIronCount = ironItems.filter(x => x.status !== 'done').length;
  const doneIronCount = ironItems.filter(x => x.status === 'done').length;
  set('stat-people', s.people ?? s.arrivals ?? 0);
  set('stat-orders', s.orders ?? s.arrivals ?? 0);
  const overtimeCount = Number(s.overtime || 0) + liveOvertime;
  const extraCount = Object.keys(getExtraRequests()).length;
  set('stat-overtime', `${extraCount}/${overtimeCount}`);
  set('stat-iron-queue', `${pendingIronCount}/${doneIronCount}`);
  const todayLedger = getTodayLedger();
  const accessorySales = todayLedger.reduce((sum, entry) => sum + (entry.receipt?.accessories || []).reduce((n, item) => n + Number(item.price || 0) * Number(item.quantity || 1), 0), 0);
  const lowStock = getAccessories().filter(x => Number(x.stock || 0) <= Number(x.alertStock ?? 10));
  const pendingCount = Object.keys(getExtraRequests()).length + new Set(states.filter(x => isOvertime(x)).map(x => x.orderId || x.seatId)).size + ironItems.filter(x => x.status !== 'done').length + lowStock.length;
  set('header-accessory-sales', `¥${accessorySales.toFixed(2)}`);
  set('stat-pending', pendingCount);
  const badge = document.getElementById('inventory-alert-badge'); if (badge) { badge.hidden = !lowStock.length; badge.textContent = lowStock.length; }
  const headerRevenue = document.getElementById('header-revenue'); if (headerRevenue) headerRevenue.textContent = `¥${Number(s.revenue).toFixed(2)}`;
}
function showOvertimeItems() { const states = Object.values(getAllSeatStates()).filter(x => isOvertime(x)); const requests = Object.values(getExtraRequests()); document.getElementById('modal-panel').innerHTML = `<div class="modal-header"><h3>⏱ 加时 / 超时订单</h3><button class="modal-close" onclick="closePanel()">✕</button></div><section class="pending-detail-group"><h4>申请加时</h4>${requests.length ? `<div class="request-list">${requests.map(x => `<div class="request-item"><strong>${x.seatId}</strong><span>+${x.minutes || '?'}分钟 · ¥${Number(x.price || 0).toFixed(1)} · ${new Date(x.time).toLocaleTimeString()}</span><button class="text-btn" onclick="selectedSeat='${x.seatId}';showExtraPanel()">处理</button></div>`).join('')}</div>` : '<div class="iron-empty">暂无加时申请</div>'}</section><section class="pending-detail-group"><h4>超时订单</h4>${states.length ? `<div class="request-list">${states.map(x => `<button class="request-item request-item-button" onclick="openSeatPanel('${x.seatId}')"><strong>${x.orderSeatIds?.join('+') || x.seatId}</strong><span>${getPackages().find(p => p.id === x.packageId)?.name || '套餐'} · 超时 ${formatTime(-getRemainingMs(x))}</span><b>查看</b></button>`).join('')}</div>` : '<div class="iron-empty">暂无超时订单</div>'}</section>`; document.getElementById('modal-overlay').classList.add('show'); }
function showPendingItems(tab = 'overtime') { const extra = Object.values(getExtraRequests()); const overtime = Object.values(getAllSeatStates()).filter(x => isOvertime(x)); const iron = getIronQueueItems().filter(x => x.request.status !== 'done'); const works = getUnfinishedWorks().filter(x => x.status !== 'done'); const tabBody = tab === 'iron' ? `<div class="pending-inline-list">${iron.length ? iron.map(ironQueueItemMarkup).join('') : '<div class="iron-empty">暂无熨烫处理</div>'}</div>` : tab === 'works' ? `<div class="pending-inline-list"><button class="text-btn" onclick="openCreateUnfinishedWork()">＋ 存图</button>${works.length ? works.map(unfinishedWorkMarkup).join('') : '<div class="iron-empty">暂无存图</div>'}</div>` : `<section class="pending-detail-group"><h4>申请加时</h4>${extra.length ? `<div class="request-list">${extra.map(x => `<div class="request-item"><strong>${x.seatId}</strong><span>+${x.minutes || '?'}分钟 · ¥${Number(x.price || 0).toFixed(1)} · ${new Date(x.time).toLocaleTimeString()}</span><button class="text-btn" onclick="selectedSeat='${x.seatId}';showExtraPanel()">处理</button></div>`).join('')}</div>` : '<div class="iron-empty">暂无加时申请</div>'}</section><section class="pending-detail-group"><h4>超时订单</h4>${overtime.length ? `<div class="request-list">${overtime.map(x => `<button class="request-item request-item-button" onclick="openSeatPanel('${x.seatId}')"><strong>${x.orderSeatIds?.join('+') || x.seatId}</strong><span>${getPackages().find(p => p.id === x.packageId)?.name || '套餐'} · 超时 ${formatTime(-getRemainingMs(x))}</span><b>查看</b></button>`).join('')}</div>` : '<div class="iron-empty">暂无超时订单</div>'}</section>`; document.getElementById('modal-panel').innerHTML = `<div class="pending-panel"><div class="pending-panel-head"><h3>待处理事项</h3><button class="text-btn" onclick="closePanel()">返回</button></div><div class="pending-tabs"><button class="pending-tab ${tab === 'overtime' ? 'active' : ''}" onclick="showPendingItems('overtime')">加时 / 超时 <b>${extra.length + overtime.length}</b></button><button class="pending-tab ${tab === 'iron' ? 'active' : ''}" onclick="showPendingItems('iron')">熨烫处理 <b>${iron.length}</b></button><button class="pending-tab ${tab === 'works' ? 'active' : ''}" onclick="showIronQueue('saved')">存图 <b>${works.length}</b></button></div>${tabBody}</div>`; document.getElementById('modal-overlay').classList.add('show'); }
function renderActionSummary() {
  const el = document.getElementById('action-summary'); if (!el) return;
  const queue = getIronQueue();
  const confirmCount = queue.filter(x => x.status === 'pending').length;
  const activeIron = queue.filter(x => x.status === 'confirmed' || x.status === 'processing').length;
  const extraRequests = Object.values(getExtraRequests());
  const extraCount = extraRequests.length;
  const lowStock = getAccessories().filter(x => Number(x.stock || 0) <= Number(x.alertStock ?? 10));
  const items = [];
  if (confirmCount) items.push(`<button onclick="showIronQueue('pending')">🔥 ${confirmCount} 个熨烫待确认</button>`);
  if (activeIron) items.push(`<button onclick="showIronQueue('pending')">🧺 ${activeIron} 个熨烫处理中</button>`);
  if (extraCount) items.push(`<button class="action-alert" onclick="showExtraRequests()">⏱ ${extraRequests.map(x => x.seatId).join('、')} 申请加时</button>`);
  if (lowStock.length) items.push(`<button onclick="openSettings();showSettingsSection('inventory', document.querySelector('.settings-nav-item'))">📦 ${lowStock.length} 项库存预警</button>`);
  el.innerHTML = items.length ? `<div class="action-summary-title">待处理事项</div><div class="action-summary-list">${items.join('')}</div>` : '<div class="action-summary-empty">待处理事项 · 当前没有需要处理的内容</div>';
}
function renderSeats() {
  const grid = document.getElementById('seats-grid');
  if (!grid) return;
  const states = getAllSeatStates();
  const seats = getManagedSeats().filter(x => x.zone === currentZone);
  grid.innerHTML = seats.map(seat => {
    const state = states[seat.id] || createSeatState(seat.id);
    const busy = state.status === 'occupied' || state.status === 'paused';
    const overtime = isOvertime(state);
    const pkg = getPackages().find(x => x.id === state.packageId);
    const left = getRemainingMs(state);
    const countdown = !busy ? '--:--' : left === Infinity ? '不限时' : overtime ? `超时 ${formatTime(-left)}` : formatTime(left);
    const color = state.orderColor ? `style="--order-color:${state.orderColor};--order-border-style:${state.orderBorderStyle || 'solid'}"` : '';
    const label = state.status === 'free' ? '空闲' : overtime ? '超时' : state.status === 'paused' ? '暂停' : '占用';
    const statusValue = state.arrivalType === '团购' ? (state.couponStatus || '未核销') : (state.paymentStatus || '未付款');
    const statusClass = statusValue === '已付款' || statusValue === '已核销' ? 'status-green' : 'status-red';
    const orderSeats = state.orderSeatIds && state.orderSeatIds.length > 1 ? state.orderSeatIds.join('+') : '';
    const animal = busy ? (state.partySize > 1 ? `${state.orderAnimal || '🐰'}${state.orderAnimal || '🐰'}` : (state.orderAnimal || '🐰')) : '';
    const start = busy && state.startTime ? new Date(state.startTime).toLocaleTimeString([], { hour:'2-digit', minute:'2-digit' }) : '--:--';
    const quickActions = busy ? `<div class="seat-quick-actions"><button onclick="quickSeatAction(event, '${seat.id}', 'pause')">${state.status === 'paused' ? '▶ 继续' : 'Ⅱ 暂停'}</button></div>` : '';
    return `<article class="seat-card ${state.status} ${!orderSeats ? 'single-seat-card' : ''} ${overtime ? 'overtime' : ''}" ${color} data-seat-id="${seat.id}" onclick="openSeatPanel('${seat.id}')">
      ${busy ? `<div class="seat-package-top">${pkg ? pkg.name : '当前套餐'}</div><div class="seat-topline"><span class="seat-status-badge ${statusClass}">${state.arrivalType || '到店'} · ${statusValue} · ¥${Number(pkg?.price || 0).toFixed(1)}</span></div>` : ''}
      <div class="seat-animals">${animal}</div>
      <div class="seat-number">${seat.id}</div>
      <div class="seat-status">${label}</div>
      <div class="seat-timer">${countdown}</div>
      <div class="seat-times"><span>开台时间：${start}</span><span>${busy ? `结束时间：${formatExpectedEnd(state)}${state.extraMinutes ? '（含加时）' : ''}` : ''}</span></div>
      <div class="seat-related">${orderSeats}</div>${quickActions}
    </article>`;
  }).join('');
}
function startTimer() {
  clearInterval(timerInterval);
  timerInterval = setInterval(() => {
    document.querySelectorAll('.seat-card').forEach(card => {
      const state = getSeatState(card.dataset.seatId);
      if (!state || (state.status !== 'occupied' && state.status !== 'paused')) return;
      const left = getRemainingMs(state);
      const el = card.querySelector('.seat-timer');
      if (el) el.textContent = left === Infinity ? '不限时' : isOvertime(state) ? `超时 ${formatTime(-left)}` : formatTime(left);
      card.classList.toggle('overtime', isOvertime(state));
    });
  }, 1000);
}

function quickSeatAction(event, seatId, action) { event.stopPropagation(); selectedSeat = seatId; const state = getSeatState(seatId); if (action === 'pause') { if (state.status === 'paused') return resumeSeat(); return pauseSeat(); } if (action === 'iron') return showIronQueue('pending'); }
function openSeatPanel(seatId) {
  selectedSeat = seatId;
  const state = getSeatState(seatId);
  if (state.status === 'free') { selectedPackageId = null; selectedPartySize = 1; selectedSeatIds = [seatId]; }
  const seat = getManagedSeats().find(x => x.id === seatId) || { id: seatId, zone: currentZone, capacity: 1 };
  const panel = document.getElementById('modal-panel');
  panel.innerHTML = state.status === 'free' ? freePanel(seat) : state.status === 'paused' ? pausedPanel(seat, state) : state.status === 'finished' ? finishedPanel(seat, state) : occupiedPanel(seat, state);
  document.getElementById('modal-overlay').classList.add('show');
}
function closePanel() { document.getElementById('modal-overlay').classList.remove('show'); selectedSeat = null; }
function freePanel(seat) {
  window.startArrivalType = '到店'; window.startStatus = '未付款';
  const single = getPackages().filter(x => x.capacity === 1);
  const multi = getPackages().filter(x => x.capacity === 2);
  const button = p => `<button class="package-btn" onclick="selectPackage('${p.id}', this)"><b>${p.name}</b><span>¥${p.price.toFixed(1)}</span></button>`;
  const freeOthers = getManagedSeats().filter(x => x.id !== seat.id && getSeatState(x.id).status === 'free');
  return `<div class="modal-header"><h3>🪑 ${seat.id} · 开台</h3><button class="modal-close" onclick="closePanel()">✕</button></div>
    <div class="party-picker"><span>本次人数</span>${[1,2,3,4].map(n => `<button class="party-btn ${n === 1 ? 'selected' : ''}" onclick="selectPartySize(${n}, this)">${n}人</button>`).join('')}</div>
    <div id="selected-seat-summary" class="seat-selection-summary">已选座位：${seat.id}</div><div id="additional-seat-select" class="additional-seat-select" style="display:none"><span>请选择关联的固定座位</span>${freeOthers.map(x => `<label><input type="checkbox" onchange="toggleOrderSeat('${x.id}', this)"> ${x.id}</label>`).join('')}</div>
    <div class="package-group" data-size="1"><div class="package-options">${single.map(button).join('')}</div></div>
    <div class="package-group" data-size="2" style="display:none"><div class="package-options">${multi.map(button).join('')}</div></div>
    <div class="choice-rows"><div class="choice-row"><span>来源</span><button class="status-tag selected" data-arrival="到店" onclick="chooseStartArrival('到店', this)">到店</button><button class="status-tag" data-arrival="团购" onclick="chooseStartArrival('团购', this)">团购</button></div><div class="choice-row" id="start-status-row"><span>状态</span><button class="status-tag selected" data-start-status="未付款" onclick="chooseStartStatus('未付款', this)">未付款</button><button class="status-tag" data-start-status="已付款" onclick="chooseStartStatus('已付款', this)">已付款</button></div></div>
    <div class="action-buttons"><button class="action-btn secondary" onclick="showSeatQr('${seat.id}')">📱 座位二维码</button><button class="action-btn primary" onclick="startSeat()">确认开台</button></div>`;
}
function selectPartySize(size, button) {
  selectedPartySize = size; selectedSeatIds = selectedSeat ? [selectedSeat] : [];
  document.querySelectorAll('.party-btn').forEach(x => x.classList.remove('selected'));
  if (button) button.classList.add('selected');
  document.querySelectorAll('.package-group').forEach(x => { x.style.display = x.dataset.size === (size === 1 ? '1' : '2') ? '' : 'none'; });
  const picker = document.getElementById('additional-seat-select'); if (picker) picker.style.display = size > 1 ? '' : 'none'; updateSeatSelectionSummary();
}
function updateSeatSelectionSummary() { const el = document.getElementById('selected-seat-summary'); if (!el) return; const required = selectedPartySize > 1 ? selectedPartySize : 1; el.textContent = `已选 ${selectedSeatIds.length}/${required} 个座位：${selectedSeatIds.join('、')}`; el.classList.toggle('ready', selectedSeatIds.length === required); }
function toggleOrderSeat(id, checkbox) { if (checkbox.checked) selectedSeatIds.push(id); else selectedSeatIds = selectedSeatIds.filter(x => x !== id); updateSeatSelectionSummary(); }
function selectPackage(id, button) { selectedPackageId = id; document.querySelectorAll('.package-btn').forEach(x => x.classList.remove('selected')); button.classList.add('selected'); }
function chooseStartArrival(value, button) { window.startArrivalType = value; window.startStatus = value === '团购' ? '未核销' : '未付款'; document.querySelectorAll('[data-arrival]').forEach(x => x.classList.toggle('selected', x === button)); const row = document.getElementById('start-status-row'); if (row) row.innerHTML = `<span>状态</span>${(value === '团购' ? ['未核销','已核销'] : ['未付款','已付款']).map((x,i) => `<button class="status-tag ${i === 0 ? 'selected' : ''}" data-start-status="${x}" onclick="chooseStartStatus('${x}', this)">${x}</button>`).join('')}`; }
function chooseStartStatus(value, button) { window.startStatus = value; document.querySelectorAll('[data-start-status]').forEach(x => x.classList.toggle('selected', x === button)); }
function startSeat() {
  if (!selectedPackageId) return showToast('请先选择套餐');
  if (selectedPartySize > 1 && selectedSeatIds.length !== selectedPartySize) return showToast(`多人订单请选择 ${selectedPartySize} 个固定座位`);
  const source = window.startArrivalType || '到店';
  const status = window.startStatus || (source === '团购' ? '未核销' : '未付款');
  const seats = selectedSeatIds.length ? selectedSeatIds : [selectedSeat];
  const orderId = `${seats.join('+')}-order_${Date.now()}`;
  const shared = { status:'occupied', packageId:selectedPackageId, orderId, orderAnimal:pickOrderAnimal(), orderColor:pickOrderColor(), orderBorderStyle:pickOrderBorderStyle(), partySize:selectedPartySize, orderSeatIds:seats, arrivalType:source, paymentStatus:source === '到店' ? status : '未付款', couponStatus:source === '团购' ? status : '未核销', isCoupon:source === '团购', startTime:Date.now(), pauseTime:null, pausedDuration:0, extraMinutes:0, needIron:false, ironDone:false, ironRequestedAt:null, ironImage:null, ironMode:null, selectedAccessories:[] };
  seats.forEach(id => updateSeatState(id, { ...shared, seatId:id }));
  updateTodayStats({ arrivals:1, people:selectedPartySize, orders:1, couponUsed:source === '团购' ? 1 : 0 });
  selectedPackageId = null; selectedPartySize = 1; selectedSeatIds = []; closePanel(); refreshAll(); showToast('已开台');
}

function occupiedPanel(seat, state) {
  const pkg = getPackages().find(x => x.id === state.packageId);
  pendingEditArrival = state.arrivalType || '到店'; pendingEditStatus = pendingEditArrival === '团购' ? (state.couponStatus || '未核销') : (state.paymentStatus || '未付款');
  const left = getRemainingMs(state);
  const seats = (state.orderSeatIds || [seat.id]).join('+');
  const statusOptions = pendingEditArrival === '团购' ? ['已核销','未核销'] : ['已付款','未付款'];
  return `<div class="modal-header"><h3>🪑 ${seats} · 使用中</h3><button class="modal-close" onclick="closePanel()">✕</button></div>
    <div class="panel-summary"><div class="panel-package">${pkg ? pkg.name : '套餐'}</div><div class="panel-countdown">${left === Infinity ? '不限时' : isOvertime(state) ? '已超时' : formatTime(left)}</div><div class="panel-meta"><span>开台时间：${new Date(state.startTime).toLocaleTimeString()}</span><span>结束时间：${formatExpectedEnd(state)}${state.extraMinutes ? '（含加时）' : ''}</span></div></div>
    <div class="status-tag-editor"><div class="choice-row"><span>来源</span><button class="status-tag ${pendingEditArrival === '到店' ? 'selected' : ''}" onclick="chooseEditStatus('到店', null, this)">到店</button><button class="status-tag ${pendingEditArrival === '团购' ? 'selected' : ''}" onclick="chooseEditStatus('团购', null, this)">团购</button></div><div class="choice-row status-save-row"><span>状态</span>${statusOptions.map(x => `<button class="status-tag ${pendingEditStatus === x ? 'selected' : ''}" onclick="chooseEditStatus(null, '${x}', this)">${x}</button>`).join('')}<button class="text-btn save-status-btn" onclick="saveOrderStatus()">保存当前状态</button></div></div>
    <div class="seat-main-actions"><button class="action-btn warning" title="暂停计时" onclick="pauseSeat()"><span>Ⅱ</span>暂停</button><button class="action-btn info" title="加时" onclick="showExtraPanel()"><span>＋</span>加时</button><button class="action-btn secondary" title="换套餐" onclick="showChangePackage()"><span>↻</span>套餐</button><button class="action-btn secondary" title="更多操作" onclick="showChangeSeat()"><span>⋯</span>更多</button><button class="action-btn secondary" title="座位二维码" onclick="showSeatQr('${seat.id}')"><span>▣</span>二维码</button></div><button class="action-btn danger checkout-panel-btn" onclick="openCheckout()">结账小票</button>`;
}
function chooseEditStatus(arrival, status, button) { if (arrival) { pendingEditArrival = arrival; pendingEditStatus = arrival === '团购' ? '未核销' : '未付款'; const state = getSeatState(selectedSeat); const seat = getManagedSeats().find(x => x.id === selectedSeat); document.getElementById('modal-panel').innerHTML = occupiedPanel(seat, state); return; } if (status) pendingEditStatus = status; document.querySelectorAll('.choice-row .status-tag').forEach(x => x.classList.remove('selected')); if (button) button.classList.add('selected'); }
function saveOrderStatus() { const state = getSeatState(selectedSeat); const updates = { arrivalType:pendingEditArrival, paymentStatus:pendingEditArrival === '到店' ? pendingEditStatus : '未付款', couponStatus:pendingEditArrival === '团购' ? pendingEditStatus : '未核销', isCoupon:pendingEditArrival === '团购' }; (state.orderSeatIds || [selectedSeat]).forEach(id => updateSeatState(id, updates)); closePanel(); refreshAll(); showToast('状态已保存并同步'); }
function showExtraRequests() { const requests = Object.values(getExtraRequests()); document.getElementById('modal-panel').innerHTML = `<div class="modal-header"><h3>⏱ 加时申请</h3><button class="modal-close" onclick="closePanel()">✕</button></div><div class="request-list">${requests.length ? requests.map(x => `<div class="request-item"><strong>${x.seatId}</strong><span>+${x.minutes || '?'}分钟 · ¥${Number(x.price || 0).toFixed(1)} · ${new Date(x.time).toLocaleTimeString()}</span><button class="text-btn" onclick="selectedSeat='${x.seatId}';showExtraPanel()">处理</button></div>`).join('') : '<div class="iron-empty">暂无加时申请</div>'}</div>`; document.getElementById('modal-overlay').classList.add('show'); }
function pauseSeat() { const state = getSeatState(selectedSeat); const ids = state.orderSeatIds || [selectedSeat]; ids.forEach(id => updateSeatState(id, { status:'paused', pauseTime:Date.now() })); closePanel(); refreshAll(); }
function resumeSeat() { const state = getSeatState(selectedSeat); const ids = state.orderSeatIds || [selectedSeat]; const pausedDelta = state.pauseTime ? Date.now() - state.pauseTime : 0; ids.forEach(id => updateSeatState(id, { status:'occupied', pauseTime:null, pausedDuration:(state.pausedDuration || 0) + pausedDelta })); closePanel(); refreshAll(); }
function showExtraPanel() { const rules = getExtraRules(); document.getElementById('modal-panel').innerHTML = `<div class="modal-header"><h3>⏱ 加时</h3><button class="modal-close" onclick="closePanel()">✕</button></div><div class="package-options">${rules.options.map(x => `<button class="package-btn" onclick="addExtra(${x.minutes}, ${x.price})">+${x.minutes}分钟<br>¥${x.price.toFixed(1)}</button>`).join('')}</div>`; }

function addExtra(minutes, price = minutes * getExtraRules().rate) { const state = getSeatState(selectedSeat); const ids = state.orderSeatIds || [selectedSeat]; ids.forEach(id => updateSeatState(id, { extraMinutes:(state.extraMinutes || 0) + minutes })); clearExtraRequest(selectedSeat); updateTodayStats({ extraCount:1, extraAmount:Number(price) }); closePanel(); refreshAll(); showToast(`已加时 ${minutes} 分钟`); }
function showChangeSeat() { const state = getSeatState(selectedSeat); const current = state.orderSeatIds || [selectedSeat]; const free = getManagedSeats().filter(x => getSeatState(x.id).status === 'free' || current.includes(x.id)); document.getElementById('modal-panel').innerHTML = `<div class="modal-header"><h3>↔️ 换座位</h3><button class="modal-close" onclick="closePanel()">✕</button></div><p class="modal-subtitle">套餐、计时、付款状态和订单信息保持不变</p><div class="seat-selection-summary ready">当前 ${(state.orderSeatIds || [selectedSeat]).join('、')} · 请选择同样数量的新座位</div><div class="change-seat-grid">${free.map(x => `<button class="change-seat-option ${current.includes(x.id) ? 'selected' : ''}" data-change-seat="${x.id}" onclick="toggleChangeSeat('${x.id}', this)">${x.id}<small>${x.zone}区</small></button>`).join('')}</div><button class="action-btn primary" style="width:100%;margin-top:14px" onclick="confirmChangeSeat()">确认换座位</button>`; window.changeSeatIds = [...current]; }
function toggleChangeSeat(id, button) { const state = getSeatState(selectedSeat); const count = (state.orderSeatIds || [selectedSeat]).length; if (count === 1) window.changeSeatIds = [id]; else if (window.changeSeatIds.includes(id)) { if (window.changeSeatIds.length > 1) window.changeSeatIds = window.changeSeatIds.filter(x => x !== id); } else if (window.changeSeatIds.length < count) window.changeSeatIds.push(id); document.querySelectorAll('.change-seat-option').forEach(x => x.classList.toggle('selected', window.changeSeatIds.includes(x.dataset.changeSeat))); }
function confirmChangeSeat() { const state = getSeatState(selectedSeat); const oldIds = state.orderSeatIds || [selectedSeat]; const newIds = window.changeSeatIds || oldIds; if (newIds.length !== oldIds.length) return showToast(`请选择 ${oldIds.length} 个座位`); oldIds.forEach(id => { if (!newIds.includes(id)) clearSeatOrder(id); }); newIds.forEach(id => updateSeatState(id, { ...state, seatId:id, orderSeatIds:newIds })); selectedSeat = newIds[0]; closePanel(); refreshAll(); showToast(`已换至 ${newIds.join('+')}，计时不变`); }
function showChangePackage() { const seat = getManagedSeats().find(x => x.id === selectedSeat); const list = getPackages().filter(x => x.capacity === ((getSeatState(selectedSeat).partySize || 1) > 1 ? 2 : 1)); document.getElementById('modal-panel').innerHTML = `<div class="modal-header"><h3>🔄 换套餐</h3><button class="modal-close" onclick="closePanel()">✕</button></div><div class="package-options">${list.map(x => `<button class="package-btn" onclick="changePackage('${x.id}')">${x.name}<br>¥${x.price}</button>`).join('')}</div>`; }
function changePackage(id) { const state = getSeatState(selectedSeat); (state.orderSeatIds || [selectedSeat]).forEach(seatId => updateSeatState(seatId, { packageId:id, extraMinutes:0 })); closePanel(); refreshAll(); showToast('套餐已更新'); }
function pausedPanel(seat, state) { return `<div class="modal-header"><h3>${seat.id} · 已暂停</h3><button class="modal-close" onclick="closePanel()">✕</button></div><div class="panel-summary"><div class="panel-package">${getPackages().find(x => x.id === state.packageId)?.name || '当前套餐'}</div><div class="panel-countdown paused-countdown">${formatTime(getElapsedMs(state))}</div><div class="panel-meta"><span>暂停时间：${state.pauseTime ? new Date(state.pauseTime).toLocaleTimeString() : '--:--'}</span><span>结束时间：${formatExpectedEnd(state)}</span></div></div><div class="seat-main-actions paused-actions"><button class="action-btn success" onclick="resumeSeat()"><span>▶</span>继续</button><button class="action-btn info" onclick="showExtraPanel()"><span>＋</span>加时</button><button class="action-btn secondary" onclick="showChangePackage()"><span>↻</span>套餐</button><button class="action-btn secondary" onclick="showSeatQr('${seat.id}')"><span>▣</span>二维码</button></div><button class="action-btn danger checkout-panel-btn" onclick="openCheckout()">结账小票</button>`; }
function finishedPanel(seat, state) { return `<div class="modal-header"><h3>${seat.id} · 已结账</h3><button class="modal-close" onclick="closePanel()">✕</button></div><button class="action-btn success" style="width:100%" onclick="resetSeat()">重置为空闲</button>`; }

function getIronQueueItems() { return getIronQueue().map(request => ({ request, seat:getManagedSeats().find(x => x.id === request.seatId) || { id:request.seatId }, state:getSeatState(request.seatId) })).sort((a,b) => (a.request.status === 'done') - (b.request.status === 'done') || a.request.requestedAt - b.request.requestedAt); }
function renderIronQueue() { return getIronQueueItems(); }
function unfinishedWorkMarkup(work) { return `<article class="unfinished-work-item"><div><strong>存图</strong><small>${work.phoneTail ? '手机尾号 ' + work.phoneTail + ' · ' : ''}${new Date(work.savedAt).toLocaleString()}</small></div>${work.image ? `<img src="${work.image}" alt="存图">` : '<span class="work-placeholder">未上传照片</span>'}<button class="text-btn" onclick="clearUnfinishedWork('${work.id}');showPendingItems('works')">移除</button></article>`; }
function showUnfinishedWorks() { showIronQueue('saved'); }
function openCreateUnfinishedWork() { document.getElementById('modal-panel').innerHTML = `<div class="modal-header"><h3>保存存图</h3><button class="modal-close" onclick="showIronQueue('saved')">返回</button></div><label class="iron-upload-label">作品照片<input id="admin-work-image" type="file" accept="image/*" onchange="showIronFile(this)"><small id="iron-file-name">点击选择图片</small></label><input id="admin-work-phone" class="admin-work-phone" inputmode="numeric" maxlength="4" placeholder="手机尾号（4位，可选）"><button class="action-btn primary" onclick="saveAdminUnfinishedWork()">保存存图</button>`; document.getElementById('modal-overlay').classList.add('show'); }
async function saveAdminUnfinishedWork() { const input = document.getElementById('admin-work-image'); const file = input?.files?.[0]; if (!file) return showToast('请先添加作品照片'); let image = null; try { image = await compressImage(file); } catch (_) { return showToast('图片读取失败，请重新选择'); } const id = `work_${Date.now()}_${Math.random().toString(36).slice(2,7)}`; saveUnfinishedWork(id, { id, image, phoneTail:document.getElementById('admin-work-phone')?.value.trim(), savedAt:Date.now() }); showIronQueue('saved'); showToast('已保存存图'); }
function ironStatusLabel(status) { return ({ pending:'待确认', confirmed:'已确认', processing:'处理中', done:'已完成' })[status] || '待确认'; }
function nextIronAction(item) { if (item.status === 'pending') return ['processing', '接单并开始制作']; if (item.status === 'confirmed') return ['processing', '开始制作']; if (item.status === 'processing') return ['done', '标记已熨']; return ['done', '已完成']; }
function ironQueueItemMarkup(x) { const position = x.request.status !== 'done' ? getIronQueuePosition(x.request.id) : ''; const action = nextIronAction(x.request); return `<article class="iron-item ${x.request.status === 'done' ? 'done' : ''}" onclick="openIronQueueItem('${x.request.id}')"><div class="iron-item-main"><strong>${x.seat.id}</strong><span>${x.request.mode || '普通熨烫'}${position ? ` · 排第 ${position}` : ''}${x.request.accessories?.length ? ' · 饰品 ' + x.request.accessories.map(id => getAccessories().find(a => a.id === id)?.name || '').filter(Boolean).join('、') : ''}</span><small>${ironStatusLabel(x.request.status)} · 提交 ${new Date(x.request.requestedAt).toLocaleTimeString()}${x.request.completedAt ? ` · 完成 ${new Date(x.request.completedAt).toLocaleTimeString()}` : ''}</small></div>${x.request.image ? `<img src="${x.request.image}" alt="拼豆图片">` : ''}<button onclick="event.stopPropagation();updateIronStatus('${x.request.id}','${action[0]}')">${action[1]}</button></article>`; }
function showIronQueue(tab = 'pending') { const list = getIronQueueItems(); const pending = list.filter(x => x.request.status !== 'done'); const done = list.filter(x => x.request.status === 'done'); const works = getUnfinishedWorks().filter(x => x.status !== 'done'); const items = tab === 'done' ? done : tab === 'saved' ? [] : pending; const pendingTotal = pending.length; const savedItems = works.filter(x => x.image).map(x => ({ seatId:x.phoneTail ? '尾号' + x.phoneTail : '未备注', image:x.image, label:'存图', time:x.savedAt })); const workMarkup = ''; const savedMarkup = tab === 'saved' ? (savedItems.length ? savedItems.map((item,index) => `<article class="saved-image-item"><b class="saved-image-number">${index + 1}</b><img src="${item.image}" alt="存图${index + 1}"><div><strong>${item.seatId} · ${item.label}</strong><small>${new Date(item.time).toLocaleString()}</small></div></article>`).join('') : '<div class="iron-empty">今天暂无存图</div>') : ''; const empty = tab !== 'saved' && !items.length && !workMarkup ? `<div class="iron-empty">暂无${tab === 'done' ? '已熨' : '未熨'}记录</div>` : ''; document.getElementById('modal-panel').innerHTML = `<div class="modal-header"><h3>🔥 熨烫处理队列</h3>${tab === 'saved' ? '<button class="text-btn" onclick="openCreateUnfinishedWork()">＋ 存图</button>' : ''}<button class="modal-close" onclick="closePanel()">✕</button></div><div class="queue-tabs"><button class="queue-tab ${tab === 'pending' ? 'active' : ''}" onclick="showIronQueue('pending')">未熨 <b>${pendingTotal}</b></button><button class="queue-tab ${tab === 'done' ? 'active' : ''}" onclick="showIronQueue('done')">已熨 <b>${done.length}</b></button><button class="queue-tab ${tab === 'saved' ? 'active' : ''}" onclick="showIronQueue('saved')">存图 <b>${savedItems.length}</b></button></div><section class="queue-group"><div class="iron-queue">${workMarkup}${items.map(ironQueueItemMarkup).join('')}${savedMarkup}${empty}</div></section>`; document.getElementById('modal-overlay').classList.add('show'); }
function openIronQueueItem(id) { const item = getIronQueue().find(x => x.id === id); if (!item) return; selectedSeat = item.seatId; const action = nextIronAction(item); document.getElementById('modal-panel').innerHTML = `<div class="modal-header"><h3>🔥 ${item.seatId} 熨烫申请</h3><button class="modal-close" onclick="closePanel()">✕</button></div><div class="iron-detail"><p>状态：${ironStatusLabel(item.status)}</p><p>队列位置：${item.status !== 'done' ? `第 ${getIronQueuePosition(item.id)} 位` : '已完成'}</p><p>提交时间：${new Date(item.requestedAt).toLocaleString()}</p><p>完成时间：${item.completedAt ? new Date(item.completedAt).toLocaleString() : '未完成'}</p><p>熨烫方式：${item.mode || '普通熨烫'}</p>${item.image ? `<img src="${item.image}" alt="拼豆图片">` : '<p class="muted">未上传图片</p>'}</div><button class="action-btn primary" style="width:100%" onclick="updateIronStatus('${id}','${action[0]}')">${action[1]}</button>`; document.getElementById('modal-overlay').classList.add('show'); }
function updateIronStatus(id, status) { const item = getIronQueue().find(x => x.id === id); if (!item) return; const updates = { status }; if (status === 'confirmed') updates.confirmedAt = Date.now(); if (status === 'processing') updates.processingAt = Date.now(); if (status === 'done') updates.completedAt = Date.now(); updateIronQueueRequest(id, updates); const state = getSeatState(item.seatId); updateSeatState(item.seatId, { ironDone:status === 'done', needIron:status !== 'done', ironStatus:status, ironRequestedAt:item.requestedAt, ironMode:item.mode, ironImage:item.image }); if (status === 'done') updateTodayStats({ needIron:-1, ironDone:1 }); closePanel(); refreshAll(); showToast(`熨烫状态：${ironStatusLabel(status)}`); }
function completeIronFromQueue(id) { updateIronStatus(id, 'done'); }

let pendingPaymentMethod = '微信收款';
let checkoutAccessoryCart = {};
let checkoutNote = '';
function checkoutAccessoryMarkup(item) { const quantity = Number(checkoutAccessoryCart[item.id] || 0); return `<article class="checkout-accessory-tag ${quantity ? 'selected' : ''}" onclick="changeCheckoutAccessory('${item.id}', 1)">${item.image ? `<img src="${item.image}" alt="">` : '<span class="checkout-accessory-placeholder">饰品</span>'}<div class="checkout-accessory-info"><b>${item.name}</b><span>¥${Number(item.price).toFixed(2)} · 库存${item.stock}</span></div><div class="checkout-qty" onclick="event.stopPropagation()"><button type="button" onclick="changeCheckoutAccessory('${item.id}', -1)">−</button><strong>${quantity}</strong><button type="button" onclick="changeCheckoutAccessory('${item.id}', 1)">＋</button></div></article>`; }
function updateCheckoutTotal() { const state = getSeatState(selectedSeat); const packageTotal = calculateAmount(state); const accessoryTotal = getAccessories().reduce((sum, item) => sum + Number(checkoutAccessoryCart[item.id] || 0) * Number(item.price || 0), 0); const set = (id, value) => { const el = document.getElementById(id); if (el) el.textContent = `¥${value.toFixed(2)}`; }; set('checkout-package-total', packageTotal); set('checkout-accessory-total', accessoryTotal); set('checkout-grand-total', packageTotal + accessoryTotal); document.querySelectorAll('.checkout-accessory-tag').forEach(card => { const id = card.querySelector('.checkout-qty button')?.getAttribute('onclick')?.match(/'([^']+)'/)?.[1]; if (id) { const qty = Number(checkoutAccessoryCart[id] || 0); card.classList.toggle('selected', qty > 0); const strong = card.querySelector('.checkout-qty strong'); if (strong) strong.textContent = qty; } }); }
function changeCheckoutAccessory(id, delta) { const item = getAccessories().find(x => x.id === id); if (!item) return; const next = Math.max(0, Math.min(Number(item.stock || 0), Number(checkoutAccessoryCart[id] || 0) + delta)); checkoutAccessoryCart[id] = next; updateCheckoutTotal(); }
function openCheckout() { const state = getSeatState(selectedSeat); const items = getAccessories().filter(x => x.category === '饰品'); pendingPaymentMethod = '微信收款'; checkoutAccessoryCart = {}; checkoutNote = ''; (state.selectedAccessories || []).filter(id => items.some(x => x.id === id)).forEach(id => { checkoutAccessoryCart[id] = Math.min(1, Number(items.find(x => x.id === id)?.stock || 0)); }); document.getElementById('modal-panel').innerHTML = `<div class="modal-header"><h3>🧾 结账</h3><button class="modal-close" onclick="closePanel()">✕</button></div><div class="receipt-checkout-head"><span>座位号${(state.orderSeatIds || [selectedSeat]).join('+')}</span><span>${getPackages().find(x => x.id === state.packageId)?.name || '套餐'}</span></div><div class="checkout-line"><span>套餐</span><strong id="checkout-package-total">¥${calculateAmount(state).toFixed(2)}</strong></div><h4 class="form-section-title">饰品</h4><p class="checkout-hint">点击商品或使用数量按钮，顾客在顾客端选的饰品已自动带入。</p><div id="checkout-accessory-list" class="checkout-accessory-grid">${items.map(checkoutAccessoryMarkup).join('')}</div><div class="checkout-line checkout-accessory-subtotal"><span>饰品小计</span><strong id="checkout-accessory-total">¥0.00</strong></div><div class="checkout-line checkout-grand-line"><span>应收合计</span><strong id="checkout-grand-total">¥${calculateAmount(state).toFixed(2)}</strong></div><h4 class="form-section-title">备注</h4><textarea id="checkout-note" class="checkout-note" placeholder="可填写顾客备注、特殊要求等"></textarea><h4 class="form-section-title">收款方式</h4><div class="payment-tags">${['微信收款','现金','支付宝','抖音团购'].map(x => `<button class="payment-tag ${x === pendingPaymentMethod ? 'selected' : ''}" onclick="selectPaymentMethod('${x}', this)">${x}</button>`).join('')}</div><button class="action-btn danger" style="width:100%;margin-top:14px" onclick="finishSeat()">确认收款并生成小票</button>`; updateCheckoutTotal(); }
function selectPaymentMethod(value, button) { pendingPaymentMethod = value; document.querySelectorAll('.payment-tag').forEach(x => x.classList.remove('selected')); button.classList.add('selected'); }
function finishSeat() { const state = getSeatState(selectedSeat); const items = getAccessories(); const note = document.getElementById('checkout-note')?.value.trim() || ''; const chosen = items.filter(item => Number(checkoutAccessoryCart[item.id] || 0) > 0).map(item => ({ ...item, quantity:Math.min(Number(checkoutAccessoryCart[item.id] || 0), Number(item.stock || 0)) })); items.forEach(item => { item.stock = Math.max(0, Number(item.stock || 0) - Number(checkoutAccessoryCart[item.id] || 0)); }); saveAccessories(items); const pkg = getPackages().find(x => x.id === state.packageId); const packageAmount = calculateAmount(state); const total = packageAmount + chosen.reduce((s,x) => s + Number(x.price) * Number(x.quantity || 1), 0); const receipt = { seatId:(state.orderSeatIds || [selectedSeat]).join('+'), orderId:state.orderId || selectedSeat, partySize:state.partySize || 1, arrivalType:state.arrivalType || '到店', packageName:pkg?.name || '套餐', packageAmount, accessories:chosen, total, paymentMethod:pendingPaymentMethod, note, createdAt:new Date().toISOString() }; saveReceipt(receipt); addLedgerEntry({ type:'收入', seatId:selectedSeat, orderId:receipt.orderId, amount:total, paymentMethod:receipt.paymentMethod, receipt, detail:receipt.packageName }); updateTodayStats({ revenue:total }); (state.orderSeatIds || [selectedSeat]).forEach(id => { if (state.workStatus === 'unfinished') saveUnfinishedWork(id, { image:state.workImage, packageName:pkg?.name, savedAt:state.workSavedAt }); else clearUnfinishedWork(id); clearSeatOrder(id); clearIronRequest(id); }); closePanel(); refreshAll(); showReceipt(receipt); }
function showReceipt(r) { document.getElementById('modal-panel').innerHTML = `<div class="modal-header"><h3>小票</h3><button class="modal-close" onclick="closePanel()">✕</button></div><div class="receipt-paper receipt-font-${getReceiptFont()}"><img class="receipt-logo" src="./assets/store-logo.png" alt="店铺标志"><div class="receipt-seat-title">座位号${r.seatId}</div><div class="receipt-rule">· · · · · · · · · · · ·</div><div class="receipt-meta"><span>时间：${new Date(r.createdAt).toLocaleString()}</span></div><div class="receipt-seat">座位：${r.seatId} · ${r.partySize}人</div><div class="receipt-items"><p><span>套餐：${r.packageName}</span><strong>¥${r.packageAmount.toFixed(2)}</strong></p>${r.note ? `<p class="receipt-note"><span>备注：${r.note}</span></p>` : ''}${r.accessories.length ? `<div class="receipt-accessory-title">饰品</div>${r.accessories.map(x => `<p><span>${x.name} ×${Number(x.quantity || 1)}</span><strong>¥${(Number(x.price) * Number(x.quantity || 1)).toFixed(2)}</strong></p>`).join('')}<p class="receipt-accessory-total"><span>饰品总价</span><strong>¥${r.accessories.reduce((s,x) => s + Number(x.price) * Number(x.quantity || 1), 0).toFixed(2)}</strong></p>` : ''}</div><div class="receipt-rule">· · · · · · · · · · · ·</div><div class="receipt-total"><span>合计</span><strong>¥${r.total.toFixed(2)}</strong></div><div class="receipt-payment">${r.paymentMethod}</div></div><button class="action-btn primary" style="width:100%;margin-top:14px" onclick="closePanel()">完成</button>`; document.getElementById('modal-overlay').classList.add('show'); }
function ledgerReceiptMarkup(x) { const r = x.receipt; return `<div class="receipt-paper ledger-receipt"><img class="receipt-logo" src="./assets/store-logo.png" alt="店铺标志"><div class="receipt-brand">咪哆豆多拼豆馆</div><div class="receipt-meta"><span>时间：${new Date(x.createdAt).toLocaleString()}</span></div><div class="receipt-seat">座位：${r?.seatId || x.seatId} · ${r?.partySize || 1}人</div><div class="receipt-items"><p><span>套餐：${r?.packageName || x.detail}</span><strong>¥${Number(r?.packageAmount || x.amount).toFixed(2)}</strong></p>${r?.note ? `<p class="receipt-note"><span>备注：${r.note}</span></p>` : ''}${(r?.accessories || []).length ? `<div class="receipt-accessory-title">饰品</div>${(r.accessories || []).map(i => `<p><span>${i.name} ×${Number(i.quantity || 1)}</span><strong>¥${(Number(i.price) * Number(i.quantity || 1)).toFixed(2)}</strong></p>`).join('')}<p class="receipt-accessory-total"><span>饰品总价</span><strong>¥${(r.accessories || []).reduce((s,i) => s + Number(i.price) * Number(i.quantity || 1), 0).toFixed(2)}</strong></p>` : ''}</div><div class="receipt-total"><span>合计</span><strong>¥${Number(x.amount).toFixed(2)}</strong></div></div>`; }
function revenueTrendMarkup(period = 'day') { const now = new Date(); const entries = getLedger().filter(x => { const d = new Date(x.createdAt); return d.getFullYear() === now.getFullYear() && (period === 'month' ? d.getMonth() === now.getMonth() : d.toDateString() === now.toDateString()); }); const labels = period === 'month' ? Array.from({length: now.getDate()}, (_,i) => `${i + 1}日`) : Array.from({length: 15}, (_,i) => `${i + 8}时`); const values = labels.map((_, i) => entries.filter(x => { const d = new Date(x.createdAt); return period === 'month' ? d.getDate() === i + 1 : d.getHours() === i + 8; }).reduce((s,x) => s + Number(x.amount || 0), 0)); const max = Math.max(...values, 1); const points = values.map((v,i) => `${(i / Math.max(values.length - 1, 1)) * 100},${92 - (v / max) * 72}`).join(' '); const shown = period === 'month' ? labels.filter((_,i) => i === 0 || (i + 1) % 5 === 0 || i === labels.length - 1) : labels.filter((_,i) => i % 2 === 0); return `<div class="trend-panel"><div class="trend-head"><div><h4>收入走势</h4><p>${period === 'month' ? '本月每日收入' : '今日分时收入'}</p></div><div class="trend-switch"><button class="trend-tab ${period === 'day' ? 'active' : ''}" onclick="showLedger('stats-day')">日</button><button class="trend-tab ${period === 'month' ? 'active' : ''}" onclick="showLedger('stats-month')">月</button></div></div><div class="trend-chart"><svg viewBox="0 0 100 100" preserveAspectRatio="none"><line x1="0" y1="92" x2="100" y2="92"></line><polyline points="${points}"></polyline></svg><div class="trend-labels">${shown.map(x => `<span>${x}</span>`).join('')}</div></div><div class="trend-total">${period === 'month' ? '本月' : '今日'}收入 <strong>¥${values.reduce((s,x) => s + x, 0).toFixed(2)}</strong></div></div>`; }
function revenueComparisonMarkup(period = 'day') { const now = new Date(); const key = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; const labels = []; const keys = []; if (period === 'month') { for (let i = 5; i >= 0; i--) { const d = new Date(now.getFullYear(), now.getMonth() - i, 1); labels.push(`${d.getMonth()+1}月`); keys.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`); } } else { for (let i = 6; i >= 0; i--) { const d = new Date(now); d.setDate(now.getDate() - i); labels.push(`${d.getMonth()+1}/${d.getDate()}`); keys.push(key(d)); } } const values = keys.map(k => getLedger().filter(x => { const d = new Date(x.createdAt); return period === 'month' ? `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}` === k : key(d) === k; }).reduce((s,x) => s + Number(x.amount || 0), 0)); const max = Math.max(...values, 1); const points = values.map((v,i) => `${(i / Math.max(values.length - 1, 1)) * 100},${92 - (v / max) * 72}`).join(' '); return `<div class="trend-panel"><div class="trend-head"><div><h4>收入对比</h4><p>${period === 'month' ? '近 6 个月每月收入' : '近 7 日每日收入'}</p></div><div class="trend-switch"><button class="trend-tab ${period === 'day' ? 'active' : ''}" onclick="showLedger('stats-day')">日</button><button class="trend-tab ${period === 'month' ? 'active' : ''}" onclick="showLedger('stats-month')">月</button></div></div><div class="trend-chart"><svg viewBox="0 0 100 100" preserveAspectRatio="none"><line x1="0" y1="92" x2="100" y2="92"></line><polyline points="${points}"></polyline></svg><div class="trend-labels">${labels.map(x => `<span>${x}</span>`).join('')}</div></div><div class="trend-total">${period === 'month' ? '近 6 个月' : '近 7 日'}收入 <strong>¥${values.reduce((s,x) => s + x, 0).toFixed(2)}</strong></div></div>`; }
function syncRevenueFromLedger() { const total = getTodayLedger().reduce((sum, item) => sum + Number(item.amount || 0), 0); const stats = getTodayStats(); stats.revenue = total; storageSet('today_stats', stats); }
function editLedgerAmount(id, value) { const amount = Math.max(0, Number(value || 0)); const ledger = getLedger().map(item => item.id == id ? { ...item, amount, receipt:item.receipt ? { ...item.receipt, total:amount } : item.receipt } : item); storageSet('ledger', ledger); syncRevenueFromLedger(); renderStats(); showLedger(); }
function addLedgerOrderFromEdit() { const seatId = document.getElementById('ledger-add-seat')?.value.trim() || '未填写'; const packageName = document.getElementById('ledger-add-package')?.value.trim() || '手动补录'; const amount = Math.max(0, Number(document.getElementById('ledger-add-amount')?.value || 0)); const paymentMethod = document.getElementById('ledger-add-payment')?.value || '微信收款'; const now = new Date().toISOString(); const receipt = { seatId, partySize:1, packageName, packageAmount:amount, accessories:[], total:amount, paymentMethod, arrivalType:'到店', createdAt:now }; addLedgerEntry({ type:'收入', seatId, amount, paymentMethod, receipt, detail:packageName }); updateTodayStats({ revenue:amount, orders:1, people:1, arrivals:1 }); syncRevenueFromLedger(); renderStats(); showLedger('receipt-edit'); showToast('已添加今日订单'); }
function deleteLedgerEntry(id) { if (!confirm('删除这条今日订单记录？')) return; const removed = getTodayLedger().find(item => item.id == id); storageSet('ledger', getLedger().filter(item => item.id != id)); if (removed) { const stats = getTodayStats(); stats.orders = Math.max(0, Number(stats.orders || 0) - 1); stats.people = Math.max(0, Number(stats.people || 0) - Number(removed.receipt?.partySize || 1)); storageSet('today_stats', stats); } syncRevenueFromLedger(); renderStats(); showLedger(); }
function downloadLedgerImage() { const list = getTodayLedger(); const canvas = document.createElement('canvas'); canvas.width = 900; canvas.height = Math.max(260, 150 + list.length * 58); const ctx = canvas.getContext('2d'); ctx.fillStyle='#fffdfb'; ctx.fillRect(0,0,canvas.width,canvas.height); ctx.fillStyle='#3b3035'; ctx.textAlign='center'; ctx.font='bold 28px Microsoft YaHei'; ctx.fillText('咪哆豆多拼豆馆 · 今日小票', canvas.width / 2, 48); ctx.font='16px Microsoft YaHei'; ctx.fillText(new Date().toLocaleDateString('zh-CN'), canvas.width / 2, 78); ctx.textAlign='left'; ctx.font='18px Microsoft YaHei'; list.forEach((item,index) => { const r=item.receipt || {}; const y=125+index*58; ctx.fillText(`座位 ${r.seatId || item.seatId}  ${r.packageName || item.detail || '套餐订单'}`, 50, y); ctx.textAlign='right'; ctx.fillText(`¥${Number(item.amount || 0).toFixed(2)}`, 850, y); ctx.textAlign='left'; ctx.strokeStyle='#eadde1'; ctx.beginPath(); ctx.moveTo(50,y+18); ctx.lineTo(850,y+18); ctx.stroke(); }); const link=document.createElement('a'); link.download=`今日小票-${new Date().toLocaleDateString('zh-CN').replace(/\\//g,'-')}.png`; link.href=canvas.toDataURL('image/png'); link.click(); }
function showLedger(mode = 'receipt') { const editing = mode === 'receipt-edit'; const list = getTodayLedger(); const total = list.reduce((s,x) => s + Number(x.amount || 0), 0); const arrivalTotal = list.filter(x => (x.receipt?.arrivalType || '到店') === '到店').reduce((s,x) => s + Number(x.amount || 0), 0); const couponTotal = list.filter(x => x.receipt?.arrivalType === '团购').reduce((s,x) => s + Number(x.amount || 0), 0); const body = mode.startsWith('stats') ? revenueComparisonMarkup(mode === 'stats-month' ? 'month' : 'day') + `<div class="ledger-stats"><div><span>到店收入</span><strong>¥${arrivalTotal.toFixed(2)}</strong></div><div><span>团购收入</span><strong>¥${couponTotal.toFixed(2)}</strong></div><div class="ledger-grand"><span>实收总计</span><strong>¥${total.toFixed(2)}</strong></div></div>` : `<div class="ledger-receipt-paper"><img class="receipt-logo" src="./assets/store-logo.png" alt="店铺标志"><div class="ledger-brand">咪哆豆多拼豆馆</div><div class="ledger-date">${new Date().toLocaleDateString('zh-CN')}</div><div class="ledger-dashed"></div><div class="ledger-summary-line"><span>今日订单</span><strong>共 ${list.length} 单 · ¥${total.toFixed(2)}</strong></div>${editing ? `<div class="ledger-add-form"><strong>添加今日订单</strong><div class="ledger-add-fields"><input id="ledger-add-seat" placeholder="座位，如 A3"><input id="ledger-add-package" placeholder="套餐名称"><input id="ledger-add-amount" type="number" min="0" step="0.1" placeholder="金额"><select id="ledger-add-payment"><option>微信收款</option><option>现金</option><option>支付宝</option><option>抖音团购</option></select><button class="text-btn" onclick="addLedgerOrderFromEdit()">添加</button></div></div>` : ''}<div class="ledger-dashed"></div><div class="ledger-orders">${list.length ? list.map(x => { const r=x.receipt || {}; return `<div class="ledger-order"><div class="ledger-order-main"><span>${new Date(x.createdAt).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})} 座位 ${r.seatId || x.seatId} ${r.packageName || String(x.detail || '套餐订单').split(' · ').slice(1).join(' · ') || '套餐订单'} · ${r.paymentMethod || x.paymentMethod || ''}</span></div>${editing ? `<div class="ledger-order-actions"><input class="ledger-amount-input" type="number" step="0.1" value="${Number(x.amount || 0).toFixed(2)}" onchange="editLedgerAmount('${x.id}', this.value)"><button class="ledger-delete" onclick="deleteLedgerEntry('${x.id}')">删除</button></div>` : `<strong>¥${Number(x.amount || 0).toFixed(2)}</strong>`}</div>`; }).join('') : '<p class="muted">今天还没有完成订单</p>'}</div><div class="ledger-dashed"></div><div class="ledger-channel"><span>到店收入</span><strong>¥${arrivalTotal.toFixed(2)}</strong></div><div class="ledger-channel"><span>团购收入</span><strong>¥${couponTotal.toFixed(2)}</strong></div><div class="ledger-grand"><span>总计</span><strong>¥${total.toFixed(2)}</strong></div><div class="ledger-footer">感谢光临</div></div>`; document.getElementById('modal-panel').innerHTML = `<div class="modal-header"><div><h3>今日小票</h3><p class="modal-subtitle">营业记录与收入汇总</p></div><button class="modal-close" onclick="closePanel()">✕</button></div><div class="ledger-tabs"><button class="ledger-tab ${mode === 'receipt' ? 'active' : ''}" onclick="showLedger('receipt')">今日小票</button><button class="ledger-tab ${mode.startsWith('stats') ? 'active' : ''}" onclick="showLedger('stats-day')">统计</button></div>${body}<div class="ledger-actions"><button class="text-btn" onclick="downloadLedgerImage()">保存图片</button>${editing ? `<button class="text-btn" onclick="showLedger('receipt')">完成修改</button>` : `<button class="text-btn" onclick="showLedger('receipt-edit')">修改小票</button>`}<button class="text-btn" onclick="clearLedger();syncRevenueFromLedger();showLedger()">清空今日记录</button></div>`; document.getElementById('modal-overlay').classList.add('show'); }

function showSeatQr(id) { const url = location.protocol === 'file:' ? `http://192.168.2.7:3000/customer.html?seat=${encodeURIComponent(id)}` : new URL(`./customer.html?seat=${encodeURIComponent(id)}`, location.href).href; const qr = `https://api.qrserver.com/v1/create-qr-code/?size=220x220&data=${encodeURIComponent(url)}`; document.getElementById('modal-panel').innerHTML = `<div class="modal-header"><h3>📱 ${id} 座位二维码</h3><button class="modal-close" onclick="closePanel()">✕</button></div><div class="qr-panel"><img src="${qr}" alt="二维码"><p>${url}</p><small class="qr-note">顾客扫码后直接打开顾客端</small></div>`; document.getElementById('modal-overlay').classList.add('show'); }
let pendingSeatZone = 'A';
let pendingSeatCapacity = 1;
let settingsSeatZone = 'A';
function openSettings() { const a = getAccessories(), m = getIronModes(); pendingSeatZone = 'A'; pendingSeatCapacity = 1; settingsSeatZone = 'A'; document.getElementById('modal-panel').innerHTML = `<div class="modal-header"><h3>⚙️ 店铺设置</h3><button class="modal-close" onclick="closePanel()">✕</button></div><div class="settings-layout"><nav class="settings-nav"><button class="settings-nav-item active" onclick="showSettingsSection('inventory', this)"><span class="settings-nav-icon">▦</span>库存管理</button><button class="settings-nav-item" onclick="showSettingsSection('iron', this)"><span class="settings-nav-icon">≋</span>熨烫方式</button><button class="settings-nav-item" onclick="showSettingsSection('extra', this)"><span class="settings-nav-icon">＋</span>加时规则</button><button class="settings-nav-item" onclick="showSettingsSection('packages', this)"><span class="settings-nav-icon">◈</span>套餐管理</button><button class="settings-nav-item" onclick="showSettingsSection('font', this)"><span class="settings-nav-icon">Aa</span>票据字体</button><button class="settings-nav-item" onclick="showSettingsSection('seats', this)"><span class="settings-nav-icon">⌂</span>座位配置</button></nav><div class="settings-detail"><section id="settings-inventory" class="settings-section"><div class="settings-section-head"><div><h4>库存</h4><p>先切换标签，再管理该标签下的商品</p></div><button class="text-btn" onclick="addInventoryTag()">＋ 添加标签</button><button class="text-btn" onclick="addAccessorySetting()">＋ 添加商品</button><button class="settings-edit-btn" onclick="toggleSettingsSectionEdit('inventory', this)">编辑</button></div><div id="inventory-tag-tabs" class="settings-filter-tabs inventory-filter-tabs"></div><div class="accessory-table-head"><span>照片</span><span>名称</span><span>价格</span><span>数量</span><span>预警</span><span>上传</span><span></span></div><div id="settings-accessories">${a.map((x,i) => accessorySettingRow(x,i)).join('')}</div></section><section id="settings-iron" class="settings-section" hidden><div class="settings-section-head"><div><h4>熨烫方式</h4><p>顾客端会同步显示这些标签</p><button class="settings-edit-btn" onclick="toggleSettingsSectionEdit('iron', this)">编辑</button></div><div id="iron-mode-tags" class="mode-tags">${m.map(x => `<button class="mode-tag" onclick="this.remove()">${x} ×</button>`).join('')}</div><div class="mode-add"><input id="new-iron-mode" placeholder="输入新的熨烫方式"><button class="text-btn" onclick="addIronModeTag()">添加</button></div></section><section id="settings-extra" class="settings-section" hidden><div class="settings-section-head"><div><h4>加时规则</h4><p>设置店员可选择的加时分钟和价格</p><button class="settings-edit-btn" onclick="toggleSettingsSectionEdit('extra', this)">编辑</button></div><div class="extra-rule-head"><span>加时分钟</span><span>加时价格</span><span></span></div><div id="extra-rule-list">${getExtraRules().options.map((x,i) => extraRuleRow(x,i)).join('')}</div><button class="text-btn" onclick="addExtraRuleRow()">＋ 添加规则</button></section><section id="settings-packages" class="settings-section" hidden><div class="settings-section-head"><div><h4>套餐管理</h4><p>预设套餐和自定义套餐都可修改名称、时间、金额和适用人数</p></div><button class="text-btn" onclick="addCustomPackageRow()">＋ 添加套餐</button><button class="settings-edit-btn" onclick="toggleSettingsSectionEdit('packages', this)">编辑</button></div><div class="settings-filter-tabs package-filter-tabs"><button class="settings-filter-tab active" data-package-tab="1" onclick="selectPackageCategory(1, this)">单人套餐</button><button class="settings-filter-tab" data-package-tab="2" onclick="selectPackageCategory(2, this)">双人套餐</button></div><div class="package-setting-head"><span>套餐名称</span><span>分钟</span><span>金额</span><span>人数</span><span></span></div><div id="custom-package-list">${getPackages().map(packageSettingRow).join('')}</div></section><section id="settings-font" class="settings-section" hidden><div class="settings-section-head"><div><h4>票据字体</h4><p>选择一套适合小票和今日订单的可爱字体</p></div><button class="settings-edit-btn" onclick="toggleSettingsSectionEdit('font', this)">编辑</button></div><div class="font-preset-list">${Object.entries(RECEIPT_FONT_PRESETS).map(([key,label]) => `<button class="font-preset ${getReceiptFont() === key ? 'selected' : ''}" data-receipt-font="${key}" onclick="selectReceiptFont('${key}', this)"><span class="font-preview font-${key}">咪哆豆多 · 今日订单</span><small>${label}</small></button>`).join('')}</div></section><section id="settings-seats" class="settings-section" hidden><div class="settings-section-head"><div><h4>座位配置</h4><p>选择区域后直接查看座位，不使用长列表</p></div><button class="settings-edit-btn" onclick="toggleSettingsSectionEdit('seats', this)">编辑</button></div><div id="settings-seat-zone-tabs" class="settings-seat-zone-tabs"><button class="settings-zone-tab active" onclick="selectSettingsSeatZone('A', this)">A区 <small>25座</small></button><button class="settings-zone-tab" onclick="selectSettingsSeatZone('B', this)">B区 <small>28座</small></button></div><div id="settings-seat-grid" class="settings-seat-grid"></div><div class="add-seat-panel"><input id="new-seat-id" placeholder="座位号，如 A26"><div class="choice-row"><span>区域</span><button class="status-tag selected" data-seat-zone="A" onclick="chooseSeatZone('A', this)">A区</button><button class="status-tag" data-seat-zone="B" onclick="chooseSeatZone('B', this)">B区</button></div><div class="choice-row"><span>类型</span><button class="status-tag selected" data-seat-capacity="1" onclick="chooseSeatCapacity(1, this)">单桌</button><button class="status-tag" data-seat-capacity="2" onclick="chooseSeatCapacity(2, this)">大桌</button></div><button class="action-btn primary" onclick="addManagedSeat()">添加座位</button></div></section></div></div><button class="action-btn primary settings-save" onclick="saveSettings()">保存</button>`; renderSettingsSeatZone('A'); selectReceiptFont(getReceiptFont(), document.querySelector(`[data-receipt-font="${getReceiptFont()}"]`)); selectInventoryCategory('accessory', document.querySelector('[data-inventory-tab="accessory"]')); selectPackageCategory(1, document.querySelector('[data-package-tab="1"]')); injectSettingsEditButtons(); document.getElementById('modal-overlay').classList.add('show'); }
function renderSettingsSeatZone(zone) { const grid = document.getElementById('settings-seat-grid'); if (!grid) return; const seats = getManagedSeats().filter(x => x.zone === zone); grid.innerHTML = seats.map(x => `<div class="settings-seat-chip"><b>${x.id}</b><small>${x.capacity === 2 ? '大桌' : '单桌'}</small><button onclick="removeManagedSeat('${x.id}')">×</button></div>`).join(''); }
function selectSettingsSeatZone(zone, button) { settingsSeatZone = zone; document.querySelectorAll('.settings-zone-tab').forEach(x => x.classList.remove('active')); button.classList.add('active'); renderSettingsSeatZone(zone); }
function showSettingsSection(name, button) { document.querySelectorAll('.settings-section').forEach(x => x.hidden = true); document.getElementById(`settings-${name}`).hidden = false; document.querySelectorAll('.settings-nav-item').forEach(x => x.classList.remove('active')); button.classList.add('active'); if (name === 'seats') renderSettingsSeatZone(settingsSeatZone); if (name === 'inventory') selectInventoryCategory('accessory', document.querySelector('[data-inventory-tab="accessory"]')); if (name === 'packages') selectPackageCategory(1, document.querySelector('[data-package-tab="1"]')); }
function chooseSeatZone(value, button) { pendingSeatZone = value; document.querySelectorAll('[data-seat-zone]').forEach(x => x.classList.toggle('selected', x === button)); }
function chooseSeatCapacity(value, button) { pendingSeatCapacity = value; document.querySelectorAll('[data-seat-capacity]').forEach(x => x.classList.toggle('selected', x === button)); }
function accessorySettingRow(x,i) { const legacyTags = { '拼豆底板':'工具', '豆夹':'工具', '豆 · 红色':'豆子', '豆 · 蓝色':'豆子', '豆 · 黄色':'豆子' }; const tag = legacyTags[x.name] || x.category || '饰品'; const withImage = tag === '饰品'; const image = withImage && x.image ? `<img class="setting-image" src="${x.image}" alt="">` : '<span class="setting-image-empty">无图</span>'; return `<div class="setting-row accessory-setting-row" data-inventory-tag="${tag}" data-id="${x.id || ''}" data-image="${x.image || ''}">${image}<input data-setting-name value="${x.name || ''}" placeholder="名称" disabled><input data-setting-price type="number" step="0.1" value="${x.price ?? 0}" placeholder="价格" disabled><input data-setting-stock type="number" value="${x.stock ?? 0}" placeholder="数量" disabled><input data-setting-alert type="number" min="0" value="${x.alertStock ?? 10}" placeholder="预警" disabled>${withImage ? '<input type="file" accept="image/*" onchange="readAccessoryImage(this)">' : '<span class="setting-image-empty">—</span>'}<button class="remove-btn" onclick="this.parentElement.remove()" disabled>删</button></div>`; }
function extraRuleRow(x) { return `<div class="extra-rule-row"><input data-extra-minutes type="number" value="${x.minutes}" placeholder="分钟" disabled><input data-extra-price type="number" step="0.1" value="${x.price}" placeholder="价格" disabled><button class="remove-btn" onclick="this.parentElement.remove()" disabled>删</button></div>`; }
function packageSettingRow(x = {}) { const removable = String(x.id || '').startsWith('custom_'); return `<div class="custom-package-row" data-package-id="${x.id || ''}" data-capacity="${Number(x.capacity) === 2 ? 2 : 1}" data-custom="${removable}"><input data-package-name value="${x.name || ''}" placeholder="套餐名称" disabled><input data-package-duration type="number" min="0" value="${x.duration ?? 60}" placeholder="分钟" disabled><input data-package-price type="number" min="0" step="0.1" value="${x.price ?? 0}" placeholder="价格" disabled><select data-package-capacity disabled><option value="1" ${Number(x.capacity) === 1 ? 'selected' : ''}>1人</option><option value="2" ${Number(x.capacity) === 2 ? 'selected' : ''}>2-4人</option></select><button class="remove-btn" onclick="this.parentElement.remove()" disabled>删</button></div>`; }
let inventoryActiveTag = '饰品';
function renderInventoryTabs() { const box = document.getElementById('inventory-tag-tabs'); if (!box) return; const tags = getInventoryTags(); if (!tags.includes(inventoryActiveTag)) inventoryActiveTag = tags[0] || ''; box.innerHTML = tags.map(tag => `<button class="settings-filter-tab ${tag === inventoryActiveTag ? 'active' : ''}" data-inventory-tag-tab="${tag}" onclick="selectInventoryTag('${tag}', this)">${tag}<span class="tag-delete" onclick="event.stopPropagation();deleteInventoryTag('${tag}')">×</span></button>`).join(''); document.querySelectorAll('#settings-accessories .accessory-setting-row').forEach(row => { row.hidden = row.dataset.inventoryTag !== inventoryActiveTag; }); }
function selectInventoryTag(tag) { inventoryActiveTag = tag; renderInventoryTabs(); }
function selectInventoryCategory(category, button) { selectInventoryTag(category === 'accessory' ? '饰品' : category === 'tool' ? '工具' : '豆子'); }
function addInventoryTag() { const tag = prompt('输入新的库存标签'); if (!tag || !tag.trim()) return; const tags = getInventoryTags(); const value = tag.trim(); if (tags.includes(value)) return showToast('标签已存在'); tags.push(value); saveInventoryTags(tags); inventoryActiveTag = value; renderInventoryTabs(); }
function deleteInventoryTag(tag) { const tags = getInventoryTags(); if (tags.length <= 1) return showToast('至少保留一个标签'); if (!confirm('删除标签“' + tag + '”？该标签下的商品也会从设置中移除。')) return; document.querySelectorAll('#settings-accessories .accessory-setting-row').forEach(row => { if (row.dataset.inventoryTag === tag) row.remove(); }); saveInventoryTags(tags.filter(x => x !== tag)); inventoryActiveTag = getInventoryTags()[0] || ''; renderInventoryTabs(); }
function selectPackageCategory(capacity, button) { document.querySelectorAll('[data-package-tab]').forEach(x => x.classList.toggle('active', x === button)); document.querySelectorAll('#custom-package-list .custom-package-row').forEach(row => { row.hidden = Number(row.dataset.capacity) !== Number(capacity); }); }
function selectReceiptFont(font, button) { saveReceiptFont(font); document.querySelectorAll('[data-receipt-font]').forEach(x => x.classList.toggle('selected', x.dataset.receiptFont === font)); }
function customPackageRow(x = {}) { return packageSettingRow({ ...x, id:x.id || `custom_${Date.now()}_${Math.random().toString(36).slice(2,7)}` }); }
function addCustomPackageRow() { document.getElementById('custom-package-list').insertAdjacentHTML('beforeend', customPackageRow()); }
function addExtraRuleRow() { document.getElementById('extra-rule-list').insertAdjacentHTML('beforeend', extraRuleRow({ minutes:30, price:6 })); }
function readAccessoryImage(input) { const f = input.files?.[0]; if (!f) return; const r = new FileReader(); r.onload = () => { const row = input.closest('.accessory-setting-row'); row.dataset.image = r.result; row.querySelector('.setting-image').src = r.result; }; r.readAsDataURL(f); }
function injectSettingsEditButtons() { document.querySelectorAll('.settings-section').forEach(section => { const head = section.querySelector('.settings-section-head'); if (!head || head.querySelector('.settings-edit-btn')) return; const button = document.createElement('button'); button.className = 'settings-edit-btn'; button.textContent = '编辑'; button.onclick = () => toggleSettingsSectionEdit(section.id.replace('settings-', ''), button); head.appendChild(button); }); }
function toggleSettingsSectionEdit(name, button) { const section = document.getElementById('settings-' + name); if (!section) return; const editing = section.classList.toggle('editing'); section.querySelectorAll('input, select').forEach(x => { if (x.type !== 'file') x.disabled = !editing; }); section.querySelectorAll('.remove-btn').forEach(x => { x.disabled = !editing; }); button.textContent = editing ? '完成' : '编辑'; }
function toggleSettingRowEdit(button) { const row = button.closest('.setting-row'); const editing = row.classList.toggle('editing'); row.querySelectorAll('input, select').forEach(x => { if (x.type !== 'file') x.disabled = !editing; }); const remove = row.querySelector('.remove-btn'); if (remove) remove.disabled = !editing; button.textContent = editing ? '完成' : '编辑'; }
function addAccessorySetting() { if (!inventoryActiveTag) return showToast('请先添加库存标签'); document.getElementById('settings-accessories').insertAdjacentHTML('beforeend', accessorySettingRow({category:inventoryActiveTag,name:'',price:0,stock:0,image:''}, 0)); const row=document.querySelector('#settings-accessories .setting-row:last-child'); row.classList.add('editing'); row.querySelectorAll('input, select').forEach(x => { x.disabled = false; }); const remove=row.querySelector('.remove-btn'); if (remove) remove.disabled=false; renderInventoryTabs(); }
function addIronModeTag() { const input = document.getElementById('new-iron-mode'); const value = input.value.trim(); if (!value) return; const tag = document.createElement('button'); tag.className = 'mode-tag'; tag.textContent = `${value} ×`; tag.onclick = () => tag.remove(); document.getElementById('iron-mode-tags').appendChild(tag); input.value = ''; }
function saveSettings() { const items = [...document.querySelectorAll('#settings-accessories .setting-row')].map(row => ({ id:row.dataset.id || `custom_${Date.now()}_${Math.random()}`, category:row.dataset.inventoryTag || '饰品', name:row.querySelector('[data-setting-name]').value.trim(), price:Number(row.querySelector('[data-setting-price]').value || 0), stock:Number(row.querySelector('[data-setting-stock]').value || 0), alertStock:Number(row.querySelector('[data-setting-alert]').value || 0), image:row.dataset.image || '' })).filter(x => x.name); const modes = [...document.querySelectorAll('#iron-mode-tags .mode-tag')].map(x => x.textContent.replace(/\s×$/, '')); const options = [...document.querySelectorAll('.extra-rule-row')].map(row => ({ minutes:Number(row.querySelector('[data-extra-minutes]').value || 0), price:Number(row.querySelector('[data-extra-price]').value || 0) })).filter(x => x.minutes > 0); const packageRows = [...document.querySelectorAll('#custom-package-list .custom-package-row')]; const packageItems = packageRows.map(row => ({ id:row.dataset.packageId || `custom_${Date.now()}_${Math.random().toString(36).slice(2,7)}`, name:row.querySelector('[data-package-name]').value.trim(), duration:Number(row.querySelector('[data-package-duration]').value || 0), price:Number(row.querySelector('[data-package-price]').value || 0), capacity:Number(row.querySelector('[data-package-capacity]').value || 1), custom:row.dataset.custom === 'true' })).filter(x => x.name && x.price >= 0 && x.duration >= 0); saveAccessories(items); saveIronModes(modes); saveExtraRules({ options, rate:options.length ? options[0].price / options[0].minutes : getExtraRules().rate }); const allPackageIds = PACKAGES.concat(getCustomPackages()).map(x => x.id); saveDeletedPackages(allPackageIds.filter(id => !packageItems.some(x => x.id === id))); savePackageOverrides(packageItems); saveCustomPackages(packageItems.filter(x => x.custom)); closePanel(); refreshAll(); showToast('设置已保存'); }
function addManagedSeat() { const id = document.getElementById('new-seat-id').value.trim().toUpperCase(); if (!id || getManagedSeats().some(x => x.id === id)) return showToast('座位号无效或已存在'); saveManagedSeats([...getManagedSeats(), {id, zone:pendingSeatZone, number:Number(id.match(/\d+/)?.[0] || 0), capacity:pendingSeatCapacity}]); openSettings(); renderSeats(); }
function removeManagedSeat(id) { if (getSeatState(id).status !== 'free') return showToast('使用中的座位不能删除'); saveManagedSeats(getManagedSeats().filter(x => x.id !== id)); openSettings(); renderSeats(); }
function resetSeat() { clearSeatOrder(selectedSeat); closePanel(); refreshAll(); }
document.addEventListener('click', e => { if (e.target.id === 'modal-overlay') closePanel(); });
